hero_mosaico.css:
.hero-mosaic { display: grid; grid-template-columns: 1fr; gap: 1.5rem; }
.hero-card { position: relative; overflow: hidden; height: 300px; background: #000; }
.hero-card img { width: 100%; height: 100%; object-fit: cover; opacity: 0.85; transition: transform 0.7s ease; }
.hero-card:hover img { transform: scale(1.05); opacity: 1; }
.hero-overlay { position: absolute; inset: 0; background: linear-gradient(to top, rgba(0,0,0,0.95) 0%, rgba(0,0,0,0.1) 80%); display: flex; flex-direction: column; justify-content: flex-end; padding: 2rem; }
.hero-title { color: #fff; font-weight: 700; line-height: 1.2; text-shadow: 2px 2px 4px rgba(0,0,0,0.5); }
@media (min-width: 992px) {
  .hero-mosaic { grid-template-columns: 2fr 1fr; grid-template-rows: 250px 250px; }
  .hero-item-0 { grid-row: 1 / -1; height: 100%; }
  .hero-item-0 .hero-title { font-size: 2.5rem; }
  .hero-item-1, .hero-item-2 { height: 100%; }
  .hero-item-1 .hero-title, .hero-item-2 .hero-title { font-size: 1.3rem; }
}

