animate_up.css:
// [7] caminho: animate_up.css
.animate-up { opacity: 0; transform: translateY(20px); transition: 0.8s cubic-bezier(0.16, 1, 0.3, 1); }
.animate-up.visible { opacity: 1; transform: translateY(0); }

animate_up.js_intersection_observer:
// [8] caminho: animate_up.js_intersection_observer
const obs = new IntersectionObserver(es => es.forEach(e => { if(e.isIntersecting) { e.target.classList.add('visible'); obs.unobserve(e.target); } }), { threshold: 0.1 });
document.querySelectorAll('.animate-up, .news-card').forEach((el, i) => {
  if(el.classList.contains('news-card')) el.style.transitionDelay = `${(i % 2) * 0.1}s`;
  el.classList.add('animate-up');
  obs.observe(el);
});

